import math
import heapq
from typing import List

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Precompute primes up to 10000
        LIMIT = 10000
        is_prime = [True] * (LIMIT + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(math.sqrt(LIMIT)) + 1):
            if is_prime[i]:
                for j in range(i*i, LIMIT + 1, i):
                    is_prime[j] = False

        # If either n or m is prime, impossible
        if is_prime[n] or is_prime[m]:
            return -1

        # Dijkstra's algorithm
        # State: (cost, current_number)
        # Priority queue: smallest cost first
        pq = [(n, n)]  # initial cost is n (since n is the first value taken)
        visited = {n}

        while pq:
            cost, curr = heapq.heappop(pq)

            if curr == m:
                return cost

            # Try to change each digit
            for i in range(len(str(curr))):
                # Build candidate numbers by modifying one digit
                # We'll create two new candidates: incremented and decremented
                # But we must avoid duplicates and check primality

                # Extract digits
                digits = list(str(curr))

                # Try incrementing
                if digits[i] != '9':
                    digits[i] = str(int(digits[i]) + 1)
                    inc_val = int("".join(digits))
                    if not is_prime[inc_val]:
                        if inc_val not in visited:
                            visited.add(inc_val)
                            heapq.heappush(pq, (cost + inc_val, inc_val))

                # Try decrementing
                if digits[i] != '0':
                    digits[i] = str(int(digits[i]) - 1)
                    dec_val = int("".join(digits))
                    if not is_prime[dec_val]:
                        if dec_val not in visited:
                            visited.add(dec_val)
                            heapq.heappush(pq, (cost + dec_val, dec_val))

        return -1

import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Precompute primes using sieve
        LIMIT = 10001
        is_prime = [True] * LIMIT
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(LIMIT**0.5)+1):
            if is_prime[i]:
                for j in range(i*i, LIMIT, i):
                    is_prime[j] = False

        # If n or m is prime, impossible
        if is_prime[n] or is_prime[m]:
            return -1

        # Determine the number of digits
        k = len(str(n))

        # Helper to check if a number is in the valid digit range for k digits
        def is_valid_range(num):
            return 10**(k-1) <= num < 10**k

        # Dijkstra's algorithm
        # State: (cost, current_number)
        pq = []
        heapq.heappush(pq, (n, n))  # cost = n, current = n

        visited = {n}

        while pq:
            cost, curr = heapq.heappop(pq)

            if curr == m:
                return cost

            # Generate next numbers by changing each digit
            s_curr = str(curr)
            # We'll iterate over each digit position
            for i in range(len(s_curr)):
                # Try increasing the digit
                if s_curr[i] != '9':
                    # Build new string
                    new_s = s_curr[:i] + str(int(s_curr[i]) + 1) + s_curr[i+1:]
                    next_val = int(new_s)

                    # Check validity
                    if is_valid_range(next_val) and not is_prime[next_val]:
                        new_cost = cost + next_val
                        if next_val not in visited:
                            visited.add(next_val)
                            heapq.heappush(pq, (new_cost, next_val))

                # Try decreasing the digit
                if s_curr[i] != '0':
                    new_s = s_curr[:i] + str(int(s_curr[i]) - 1) + s_curr[i+1:]
                    next_val = int(new_s)

                    if is_valid_range(next_val) and not is_prime[next_val]:
                        new_cost = cost + next_val
                        if next_val not in visited:
                            visited.add(next_val)
                            heapq.heappush(pq, (new_cost, next_val))

        return -1
